 const portrait=program(`precision highp float;attribute vec2 aUV;uniform vec2 uResolution;uniform vec4 uPortrait;varying vec2 vUV;void main(){vUV=aUV;vec2 p=uPortrait.xy+aUV*uPortrait.zw;gl_Position=vec4(p.x/uResolution.x*2.-1.,1.-p.y/uResolution.y*2.,0.,1.);}`,
 `precision highp float;uniform sampler2D uImage;uniform float uTime,uMirror,uTransfer,uRole;varying vec2 vUV;${timing}void main(){vec2 uv=vec2(mix(vUV.x,1.-vUV.x,uMirror),vUV.y);vec4 color=texture2D(uImage,uv);float gate;if(uRole<-.5)gate=1.-smoothstep(.015,.30,transferPhase(uv,uTransfer));else if(uRole>.5)gate=smoothstep(.72,.985,transferPhase(uv,uTransfer));else gate=smoothstep(.75,.985,arrival(uv,uTime));gl_FragColor=vec4(color.rgb,color.a*gate);}`);
